  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
}

/* Create a custom checkbox */
.checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  background-color: #ccc;
  border-bottom-left-radius: 15px;
  border-top-right-radius: 15px;
  box-shadow: 0px 0px 17px #c7bbb8;
